function trCore(t){let r=I18N_EN[t];if(r!==undefined)return r;for(const [rx,rep] of I18N_RX){if(rx.test(t))return t.replace(rx,rep)}return undefined}
function trEN(s){
  const t=s.trim();if(!t||!/[A-Za-zÀ-ÿ]/.test(t))return null;
  let r=trCore(t);
  if(r===undefined&&t.includes(' · ')){const p=t.split(' · ');const q=p.map(x=>{const y=x.trim();if(/^\(.+\)$/.test(y)){const v=trCore(y.slice(1,-1));return v!==undefined?'('+v+')':x}const v=trCore(y);return v!==undefined?v:x});if(q.some((x,i)=>x!==p[i]))r=q.join(' · ')}
  if(r===undefined&&/^\(.+\)$/.test(t)){const inner=t.slice(1,-1).split(' · ');const q=inner.map(y=>{const v=trCore(y);return v!==undefined?v:y});if(q.some((x,i)=>x!==inner[i]))r='('+q.join(' · ')+')'}
  if(r===undefined)return null;
  const lead=s.match(/^\s*/)[0],trail=s.match(/\s*$/)[0];return lead+r+trail;
}
let LANG='fr';try{LANG=localStorage.getItem('salama_wms_lang')||'fr'}catch(e){}
const I18N_ATTR=['placeholder','title','aria-label'];
function i18nNode(root){
  if(LANG!=='en'||!root)return;
  if(root.nodeType===3){if(!root.__fr){const r=trEN(root.nodeValue);if(r!==null){root.__fr=root.nodeValue;root.nodeValue=r}}return}
  if(root.nodeType!==1)return;
  const tag=root.tagName;if(tag==='SCRIPT'||tag==='STYLE'||tag==='TEXTAREA'||tag==='svg'||tag==='SVG')return;
  const walk=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>{const p=n.parentNode&&n.parentNode.closest&&n.parentNode.closest('script,style,textarea,svg,[data-noi18n]');return p?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT}});
  let n;const list=[];while(n=walk.nextNode())list.push(n);
  list.forEach(x=>{const r=trEN(x.nodeValue);if(r!==null){x.__fr=x.nodeValue;x.nodeValue=r}});
  const els=[root,...root.querySelectorAll('[placeholder],[title],[aria-label]')];
  els.forEach(e=>I18N_ATTR.forEach(a=>{if(e.hasAttribute&&e.hasAttribute(a)&&!e['__fr_'+a]){const r=trEN(e.getAttribute(a));if(r!==null){e['__fr_'+a]=e.getAttribute(a);e.setAttribute(a,r)}}}));
}
let I18N_OBS=null;
function i18nApply(){
  document.documentElement.lang=LANG;
  if(I18N_OBS){I18N_OBS.disconnect();I18N_OBS=null}
  const root=document.getElementById('root');if(!root)return;
  if(LANG==='en'){
    i18nNode(root);
    I18N_OBS=new MutationObserver(ms=>{ms.forEach(m=>m.addedNodes.forEach(i18nNode))});
    I18N_OBS.observe(root,{childList:true,subtree:true});
  }
  const b=document.getElementById('langBtn');if(b)b.innerHTML=LANG==='en'?'<b>EN</b> | FR':'<b>FR</b> | EN';
}
function langToggle(){
  LANG=LANG==='en'?'fr':'en';try{localStorage.setItem('salama_wms_lang',LANG)}catch(e){}
  if(typeof audit==='function')audit('Langue de l’interface','Paramètre',LANG.toUpperCase());
  if(typeof save==='function')save();shell();render();
}
const _shell_i18n=shell;
function addLangBtn(){
  const top=document.querySelector('header.top');
  if(top&&!document.getElementById('langBtn')){const b=document.createElement('button');b.className='btn';b.id='langBtn';b.type='button';b.title='Langue / Language';b.setAttribute('data-noi18n','');b.onclick=langToggle;top.insertBefore(b,document.getElementById('netPill'));}
}
shell=function(){_shell_i18n.apply(this,arguments);addLangBtn();i18nApply()};
if(document.querySelector('header.top')){addLangBtn();i18nApply()}
